import React, { useCallback, useMemo, useState } from 'react';
import {
  Button,
  Input,
  dispatchAppToast,
  getActiveCompanyCode,
  getAuthUser,
  LinPageLayout,
  useCatalogTableBusy,
  type LinListToolbarActionDef,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { analyticsService } from '../../../services/analytics/analyticsService';
import type { CashDisbursementJournalRow } from '../../../services/analytics/models';
import { formatDate, formatVnd } from '../../../utils/formatters';
import { exportExcel, monthStartEnd } from '../../../utils/exportExcel';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import erp from '../../../styles/erpPage.module.css';
import reportStyles from '../../../styles/erpReportPage.module.css';
import styles from './SoNhatKyChiTienPage.module.css';

const TEST_ID = 'rpt-so-nhat-ky-chi-tien';
const PAGE_ID = 'baocao-so-nhat-ky-chi-tien';
const TITLE = 'Sổ nhật ký chi tiền';
const DEFAULT_CREDIT = '111,112';

type RowTag = 'Detail' | 'Total' | 'Blank';

function sessionCompany(): string {
  return (getActiveCompanyCode() ?? getAuthUser()?.companyCode ?? '').trim();
}

function mapRowTag(raw: CashDisbursementJournalRow['rowTag'], isTotal?: boolean): RowTag {
  if (raw === 'Total' || isTotal) return 'Total';
  if (raw === 'Blank') return 'Blank';
  return 'Detail';
}

function normalizeItems(items: CashDisbursementJournalRow[]): CashDisbursementJournalRow[] {
  return items.map(r => {
    const rowTag = mapRowTag(r.rowTag, r.isTotal);
    const isTotal = rowTag === 'Total' || Boolean(r.isTotal);
    return {
      ...r,
      rowTag,
      isTotal,
      isBold: Boolean(r.isBold) || isTotal,
    };
  });
}

function rowClass(tag: RowTag): string | undefined {
  if (tag === 'Total') return styles.rowToneTotal;
  if (tag === 'Blank') return styles.rowBlank;
  return styles.rowToneDetail;
}

const SoNhatKyChiTienPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const monthRange = monthStartEnd();

  const [fromDate, setFromDate] = useState(monthRange.fromDate);
  const [toDate, setToDate] = useState(monthRange.toDate);
  const [creditAccountList, setCreditAccountList] = useState(DEFAULT_CREDIT);

  const [items, setItems] = useState<CashDisbursementJournalRow[]>([]);
  const [appliedFrom, setAppliedFrom] = useState('');
  const [appliedTo, setAppliedTo] = useState('');
  const [appliedCreditList, setAppliedCreditList] = useState('');
  const [hasViewed, setHasViewed] = useState(false);
  const [loading, setLoading] = useState(false);
  const [filterError, setFilterError] = useState('');
  const { showTableLoading } = useCatalogTableBusy(loading);

  const summary = useMemo(() => {
    if (!hasViewed) return null;
    const total = items.find(r => mapRowTag(r.rowTag, r.isTotal) === 'Total');
    if (!total) return null;
    return { amount: Number(total.amount ?? 0) };
  }, [hasViewed, items]);

  const detailCount = useMemo(
    () => items.filter(r => mapRowTag(r.rowTag, r.isTotal) === 'Detail').length,
    [items],
  );

  const handleView = useCallback(() => {
    setFilterError('');
    const company = sessionCompany();
    if (!company) {
      setFilterError('Không xác định đơn vị');
      dispatchAppToast(dispatch, { message: 'Không xác định đơn vị', type: 'error' });
      return;
    }
    const from = fromDate.trim();
    const to = toDate.trim();
    if (!from || !to) {
      setFilterError('Chọn khoảng ngày');
      dispatchAppToast(dispatch, { message: 'Chọn khoảng ngày', type: 'error' });
      return;
    }
    if (to < from) {
      setFilterError('Đến ngày phải ≥ Từ ngày');
      dispatchAppToast(dispatch, { message: 'Đến ngày phải ≥ Từ ngày', type: 'error' });
      return;
    }
    // Empty credit → normalize 111,112 (parity token). Cấm silent empty→all Có.
    const credit = creditAccountList.trim() || DEFAULT_CREDIT;
    if (!creditAccountList.trim()) {
      setCreditAccountList(DEFAULT_CREDIT);
    }

    setLoading(true);
    analyticsService
      .getCashDisbursementJournal({
        fromDate: from,
        toDate: to,
        creditAccountList: credit,
        pageSize: 0,
      })
      .then(report => {
        setItems(normalizeItems(report.items ?? []));
        setAppliedFrom(from);
        setAppliedTo(to);
        setAppliedCreditList(credit);
        setHasViewed(true);
      })
      .catch(err => {
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không tải được sổ nhật ký chi tiền'),
          type: 'error',
        });
      })
      .finally(() => setLoading(false));
  }, [creditAccountList, dispatch, fromDate, toDate]);

  const onEnterView = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleView();
      }
    },
    [handleView],
  );

  const handleRefresh = useCallback(() => {
    const range = monthStartEnd();
    setFromDate(range.fromDate);
    setToDate(range.toDate);
    setCreditAccountList(DEFAULT_CREDIT);
    setFilterError('');
  }, []);

  const handleExport = useCallback(() => {
    if (!hasViewed || loading || !appliedFrom || !appliedTo) return;
    const fileName = `so-nhat-ky-chi-tien_${appliedFrom}_${appliedTo}.xlsx`;
    void exportExcel(
      '/accounting/cash-disbursement-journal/export-excel',
      {
        fromDate: appliedFrom,
        toDate: appliedTo,
        creditAccountList: appliedCreditList || DEFAULT_CREDIT,
        pageSize: 0,
      },
      fileName,
    ).catch(() => {
      /* toast already in exportExcel */
    });
  }, [appliedCreditList, appliedFrom, appliedTo, hasViewed, loading]);

  const handlePrint = useCallback(() => {
    window.print();
  }, []);

  const exportDisabled = !hasViewed || loading || !appliedFrom;

  const toolbarActions = useMemo<LinListToolbarActionDef[]>(
    () => [
      {
        id: 'refresh',
        action: 'refresh',
        placement: 'left',
        label: 'Làm mới',
        variant: 'secondary',
        testId: `${TEST_ID}-toolbar-refresh-btn`,
        disabled: loading,
        onClick: handleRefresh,
      },
      {
        id: 'export-excel',
        action: 'exportExcel',
        placement: 'left',
        label: 'Xuất Excel',
        variant: 'secondary',
        testId: `${TEST_ID}-export-excel`,
        disabled: exportDisabled,
        onClick: handleExport,
      },
      {
        id: 'print',
        action: 'print',
        placement: 'left',
        label: 'In',
        variant: 'secondary',
        testId: `${TEST_ID}-export-print`,
        disabled: !hasViewed || loading,
        onClick: handlePrint,
      },
    ],
    [exportDisabled, handleExport, handlePrint, handleRefresh, hasViewed, loading],
  );

  const subtitle =
    hasViewed && appliedFrom && appliedTo
      ? `Từ: ${formatDate(appliedFrom)} đến ngày ${formatDate(appliedTo)}`
      : undefined;

  const listBody = showTableLoading ? null : (
    <div className={erp.tableWrapper}>
      {subtitle ? (
        <div data-testid={`${TEST_ID}-subtitle`} className={reportStyles.subtitle} style={{ marginBottom: '0.5rem' }}>
          {subtitle}
        </div>
      ) : null}
      <table className={reportStyles.table} data-testid={`${TEST_ID}-grid`}>
        <thead>
          <tr>
            <th>Số CT</th>
            <th>Ngày CT</th>
            <th>Mã KH</th>
            <th>Tên KH</th>
            <th>Diễn giải</th>
            <th>TK nợ</th>
            <th>TK có</th>
            <th className={reportStyles.colRight}>Thành tiền</th>
            <th>Phí</th>
            <th>HĐ</th>
            <th>SP</th>
          </tr>
        </thead>
        <tbody>
          {!hasViewed
            ? null
            : items.map((row, index) => {
                const tag = mapRowTag(row.rowTag, row.isTotal);
                const isTotal = tag === 'Total';
                const isBlank = tag === 'Blank';
                return (
                  <tr
                    key={`${tag}|${row.voucherCode ?? ''}|${row.entryDate ?? ''}|${row.creditAccountCode ?? ''}|${index}`}
                    className={rowClass(tag)}
                    data-testid={`${TEST_ID}-row-${index}`}
                    data-row-tag={tag}
                    data-is-total={isTotal ? '1' : '0'}
                    data-drillable="0"
                    aria-hidden={isBlank ? true : undefined}
                  >
                    <td>{isBlank || isTotal ? '' : (row.voucherCode ?? '')}</td>
                    <td>{isBlank || isTotal || !row.entryDate ? '' : formatDate(row.entryDate)}</td>
                    <td>{isBlank || isTotal ? '' : (row.customerCode ?? '')}</td>
                    <td>{isBlank ? '' : (row.customerName ?? '')}</td>
                    <td>{isBlank || isTotal ? '' : (row.description ?? '')}</td>
                    <td>{isBlank || isTotal ? '' : (row.debitAccountCode ?? '')}</td>
                    <td>{isBlank || isTotal ? '' : (row.creditAccountCode ?? '')}</td>
                    <td className={reportStyles.colRight}>
                      {isBlank || row.amount == null ? '' : formatVnd(Number(row.amount))}
                    </td>
                    <td>{isBlank || isTotal ? '' : (row.feeCode ?? '')}</td>
                    <td>{isBlank || isTotal ? '' : (row.contractCode ?? '')}</td>
                    <td>{isBlank || isTotal ? '' : (row.productCode ?? '')}</td>
                  </tr>
                );
              })}
        </tbody>
      </table>
      {hasViewed && detailCount === 0 ? (
        <div className={erp.empty} data-testid={`${TEST_ID}-empty`}>
          Không có dữ liệu
        </div>
      ) : null}
    </div>
  );

  const footer =
    hasViewed && summary ? (
      <div className={styles.summaryBar} data-testid={`${TEST_ID}-summary`}>
        <span>Thành tiền: {formatVnd(summary.amount)}</span>
      </div>
    ) : undefined;

  return (
    <div
      className={erp.voucherListRoot}
      data-catalog-list-page
      data-report-list-page
      data-testid={`${TEST_ID}-list`}
    >
      <LinPageLayout
        kind="report"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        pageClassName={`${erp.catalogListPage} ${erp.voucherListPage}`}
        header={{ title: TITLE, titleIconClass: 'fas fa-money-bill-wave' }}
        listTitle={TITLE}
        filterMaxWidthPx={1200}
        showTableLoading={showTableLoading}
        skeletonRows={8}
        toolbarProps={{
          testIdPrefix: TEST_ID,
          profile: 'report',
          actions: toolbarActions,
        }}
        footer={footer}
        filters={(
          <>
            <div data-testid={`${TEST_ID}-field-fromDate`}>
              <Input
                type="date"
                label="Từ ngày"
                value={fromDate}
                onChange={e => setFromDate(e.target.value)}
                onKeyDown={onEnterView}
                data-testid={`${TEST_ID}-field-from`}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-toDate`}>
              <Input
                type="date"
                label="Đến ngày"
                value={toDate}
                onChange={e => setToDate(e.target.value)}
                onKeyDown={onEnterView}
                data-testid={`${TEST_ID}-field-to`}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-creditAccountList`}>
              <Input
                label="TK có (chi)"
                value={creditAccountList}
                onChange={e => setCreditAccountList(e.target.value)}
                onKeyDown={onEnterView}
                placeholder="111,112"
                data-testid={`${TEST_ID}-field-credit`}
              />
            </div>
            <Button
              variant="primary"
              onClick={handleView}
              disabled={loading}
              data-testid={`${TEST_ID}-view-btn`}
            >
              Xem
            </Button>
            {filterError ? (
              <div className={styles.filterError} data-testid={`${TEST_ID}-filter-error`}>
                {filterError}
              </div>
            ) : null}
          </>
        )}
      >
        {listBody}
      </LinPageLayout>
    </div>
  );
};

export default SoNhatKyChiTienPage;
